<?php
// Standalone domain service: no session globals, network calls or legacy writes.
function coNow(){return (new DateTimeImmutable('now',new DateTimeZone('America/Lima')))->format('Y-m-d H:i:s');}
function coJson($value){return json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
function coText($value,$max,$required=false){if(!is_string($value)||mb_strlen($value)>$max||($required&&trim($value)===''))throw new InvalidArgumentException('Revisa el texto y su longitud.');return trim($value);}
function coDate($value){$v=(string)$value;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new InvalidArgumentException('Fecha inválida.');return $v;}
function coPeriod($value){if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',(string)$value))throw new InvalidArgumentException('Período inválido: usa AAAA-MM.');return (string)$value;}
function coMoney($value,$negative=false){
 if(is_float($value))$value=rtrim(rtrim(sprintf('%.8F',$value),'0'),'.');$s=(string)$value;
 if(!preg_match('/^(-?)(\d{1,7})(?:\.(\d{1,2}))?$/',$s,$m))throw new InvalidArgumentException('Importe inválido: máximo dos decimales y 9,999,999.99.');
 $c=(int)$m[2]*100+(int)str_pad($m[3]??'',2,'0');if($m[1]==='-')$c=-$c;if(!$negative&&$c<0)throw new InvalidArgumentException('El importe no puede ser negativo.');return $c;
}
function coAmount($cents){return ($cents<0?'-':'').intdiv(abs($cents),100).'.'.str_pad((string)(abs($cents)%100),2,'0',STR_PAD_LEFT);}
function coRate($value){$s=(string)$value;if(strpos($s,'.')!==false)$s=rtrim(rtrim($s,'0'),'.');if(!preg_match('/^(\d{1,4})(?:\.(\d{1,6}))?$/',$s,$m))throw new InvalidArgumentException('Tipo de cambio inválido: hasta seis decimales.');$rate=(int)$m[1]*1000000+(int)str_pad($m[2]??'',6,'0');if($rate<=0||$rate>1000000000)throw new InvalidArgumentException('Tipo de cambio fuera de rango.');return $rate;}
function coConvert($cents,$rate){$n=$cents*$rate;if(!is_int($n))throw new InvalidArgumentException('Importe convertido fuera de rango.');return intdiv($n+500000,1000000);}
function coRuc($value){if(!preg_match('/^(10|15|16|17|20)\d{9}$/',(string)$value))return false;$sum=0;foreach([5,4,3,2,7,6,5,4,3,2] as $i=>$w)$sum+=(int)$value[$i]*$w;$digit=11-$sum%11;if($digit===10)$digit=0;elseif($digit===11)$digit=1;return $digit===(int)$value[10];}
function coElectronic(array $p){$idType=(string)($p['issuerType']??'');$id=coText($p['issuerDoc']??'',15,true);if(!in_array($idType,['0','1','4','6','7','A'],true)||($idType==='6'&&!coRuc($id))||($idType==='1'&&!preg_match('/^\d{8}$/',$id)))throw new InvalidArgumentException('Identidad electrónica inválida.');$type=coText($p['docType']??'',2,true);if(!preg_match('/^\d{2}$/',$type))throw new InvalidArgumentException('Tipo de documento electrónico inválido.');$ref=coText($p['reference']??'',92);if($ref!==''&&!preg_match('/^(140100|080100|080200)&\d{6}00&[A-Za-z0-9_-]{1,40}&[AMC][A-Za-z0-9_-]{1,9}$/',$ref))throw new InvalidArgumentException('Referencia de registro electrónico inválida.');return ['issuerType'=>$idType,'issuerDoc'=>$id,'docType'=>$type,'series'=>coText($p['series']??'',20),'number'=>coText($p['number']??'',24,true),'reference'=>$ref];}
function coTax(array $d){
 $kind=$d['kind']??'';if(!in_array($kind,['sale','purchase'],true))throw new InvalidArgumentException('Registro tributario inválido.');
 $type=$d['docType']??'';if(!in_array($type,['01','03','07','08','12','14','16','18','23','30','34','35','36','37','42','48','50','52','54','87','88','89','91','96','97','98'],true))throw new InvalidArgumentException('Tipo de comprobante inválido.');
 $partyType=(string)($d['partyDocType']??'');$party=(string)($d['partyDoc']??'');if(!in_array($partyType,['0','1','4','6','7','A'],true))throw new InvalidArgumentException('Tipo de identidad no disponible.');$party=coText($party,20,$partyType!=='0');
 if($partyType==='6'&&!coRuc($party))throw new InvalidArgumentException('RUC inválido.');if($partyType==='1'&&!preg_match('/^\d{8}$/',$party))throw new InvalidArgumentException('DNI inválido.');
 if($kind==='purchase'&&$partyType!=='6')throw new InvalidArgumentException('Registra la compra no domiciliada u otro documento como ajuste revisado, no como factura nacional.');
 $date=coDate($d['issueDate']??'');if($date>substr(coNow(),0,10))throw new InvalidArgumentException('El comprobante no puede tener fecha futura.');if(isset($d['creditEligible'])&&!is_bool($d['creditEligible']))throw new InvalidArgumentException('Revisa el derecho a crédito fiscal.');$period=coPeriod($d['period']??substr($date,0,7));if($period<substr($date,0,7))throw new InvalidArgumentException('El período tributario precede la emisión.');
 $row=['kind'=>$kind,'issueDate'=>$date,'period'=>$period,'docType'=>$type,'series'=>coText($d['series']??'',20,true),'number'=>coText((string)($d['number']??''),30,true),'partyDocType'=>$partyType,'partyDoc'=>$party,'partyName'=>coText($d['partyName']??'',200,true),'creditEligible'=>!empty($d['creditEligible']),'referenceDoc'=>coText($d['referenceDoc']??'',100)];
 foreach(['taxable','exempt','unaffected','freeAmount','freeIgv','igv','otherTaxes','total','withholding','perception','detraction'] as $k)$row[$k]=coMoney($d[$k]??'0');
 if($row['taxable']+$row['exempt']+$row['unaffected']+$row['igv']+$row['otherTaxes']!==$row['total'])throw new InvalidArgumentException('Base, IGV y total del documento no coinciden.');
 if($row['freeIgv']>0&&$row['freeAmount']===0)throw new InvalidArgumentException('IGV gratuito sin valor referencial.');if($row['taxable']===0&&$row['igv']!==0)throw new InvalidArgumentException('IGV sin base gravada.');
 if($type==='07'&&$row['referenceDoc']==='')throw new InvalidArgumentException('La nota de crédito requiere comprobante de referencia.');
 if($row['withholding']+$row['detraction']>$row['total'])throw new InvalidArgumentException('Retención/detracción excede el importe.');
 $row['sign']=$type==='07'?-1:1;return $row;
}
class CoService {
 public $db,$user,$super;
 public function __construct(PDO $db,$user,$super=false){if(PHP_INT_SIZE<8)throw new RuntimeException('Contabilidad requiere PHP de 64 bits.');$this->db=$db;$this->user=$user;$this->super=$super;}
 public function rows($sql,$args=[]){$s=$this->db->prepare($sql);$s->execute($args);return $s->fetchAll(PDO::FETCH_ASSOC);}
 public function one($sql,$args=[]){return $this->rows($sql,$args)[0]??null;}
 public function exec($sql,$args=[]){$s=$this->db->prepare($sql);$s->execute($args);return $s->rowCount();}
 public function transaction(callable $fn){if($this->db->inTransaction())throw new LogicException('Transacción contable anidada.');$this->db->beginTransaction();try{$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function permit($company,$action='read'){
  if(!$this->super&&!$this->one('SELECT Usuario FROM Seg_Usuario WHERE Usuario=? AND COALESCE(Anulado,0)=0',[$this->user]))throw new DomainException('Usuario contable inactivo.');
  $c=$this->one('SELECT * FROM Co_Company WHERE Id=? AND Active=1',[$company]);if(!$c)throw new DomainException('Empresa no disponible.');
  $role=$this->super?'admin':($this->one('SELECT Role FROM Co_Member WHERE CompanyId=? AND Username=?',[$company,$this->user])['Role']??'');
  $rights=['admin'=>['read','draft','review','approve','post','reverse','manage','period','reconcile','export'],'accountant'=>['read','draft','review','approve','post','reverse','period','reconcile','export'],'assistant'=>['read','draft','reconcile','export'],'auditor'=>['read','export'],'manager'=>['read','approve','export']];
  if(!in_array($action,$rights[$role]??[],true))throw new DomainException('Sin permiso contable para esta acción.');$c['role']=$role;$c['settings']=json_decode($c['Config'],true)?:[];return $c;
 }
 public function audit($company,$action,$entity,$id,$data=[]){$this->exec('INSERT INTO Co_Audit(CompanyId,Username,Action,Entity,EntityId,Data,CreatedAt) VALUES(?,?,?,?,?,?,?)',[$company,$this->user,$action,$entity,(string)$id,coJson($data),coNow()]);}
 public function companies(){if($this->super)return $this->rows('SELECT Id,Name,Ruc,Currency,Regime,Obligation,Version FROM Co_Company WHERE Active=1 ORDER BY Name');return $this->rows('SELECT c.Id,c.Name,c.Ruc,c.Currency,c.Regime,c.Obligation,c.Version,m.Role FROM Co_Company c JOIN Co_Member m ON m.CompanyId=c.Id WHERE m.Username=? AND c.Active=1 ORDER BY c.Name',[$this->user]);}
 public function company(array $p){
  if(!$this->super)throw new DomainException('Solo superadmin puede crear empresas.');if(!coRuc($p['ruc']??''))throw new InvalidArgumentException('RUC de empresa inválido.');
  if(!in_array($p['regime']??'', ['general','mype','rer','rus','other'],true)||!in_array($p['obligation']??'none',['none','sire','ple'],true))throw new InvalidArgumentException('Configura régimen y obligación.');
  return $this->transaction(function()use($p){$this->exec('INSERT INTO Co_Company(Name,Ruc,Currency,Regime,Obligation,Config) VALUES(?,?,?,?,?,?)',[coText($p['name']??'',200,true),$p['ruc'],'PEN',$p['regime'],$p['obligation']??'none',coJson(['fourEyes'=>true,'accounts'=>[],'taxRate'=>'18.00','taxReviewed'=>false])]);$id=(int)$this->db->lastInsertId();$this->audit($id,'create','company',$id);return ['id'=>$id];});
 }
 public function configure($company,array $p){
  $this->permit($company,'manage');return $this->transaction(function()use($company,$p){$c=$this->one('SELECT * FROM Co_Company WHERE Id=? FOR UPDATE',[$company]);if((int)$c['Version']!==(int)($p['version']??0))throw new InvalidArgumentException('La configuración cambió. Recarga.');
   $cfg=$p['settings']??[];if(!is_array($cfg)||!is_array($cfg['accounts']??null))throw new InvalidArgumentException('Configuración inválida.');
   $allowedKeys=['cash','bank','bank_fees','receivable','payable','inventory','purchase_goods','inventory_variation','sales_goods','sales_services','cost_goods','igv_output','igv_input','expense','other_income','other_tax_payable','inventory_adjustment','inventory_loss','payroll','payroll_payable','retained','withholding_credit','withholding_payable','perception_credit','perception_payable','restricted_bank','free_delivery_expense','free_tax_expense'];foreach($cfg['accounts'] as $key=>$code){if(!in_array($key,$allowedKeys,true))throw new InvalidArgumentException('Cuenta predeterminada desconocida.');if(!preg_match('/^[a-z_]{1,40}$/',$key)||!$this->one('SELECT Code FROM Co_Account WHERE CompanyId=? AND Code=? AND Active=1 AND Postable=1',[$company,$code]))throw new InvalidArgumentException('Cuenta predeterminada no válida: '.$key);}
   if(!is_bool($cfg['fourEyes']??null)||!is_bool($cfg['taxReviewed']??null))throw new InvalidArgumentException('Revisa las opciones de control.');$taxRate=coMoney($cfg['taxRate']??'18');if($taxRate>10000)throw new InvalidArgumentException('Tasa tributaria fuera de rango.');$this->exec('UPDATE Co_Company SET Config=?,Version=Version+1 WHERE Id=?',[coJson($cfg),$company]);$this->audit($company,'configure','company',$company,['before'=>json_decode($c['Config'],true),'after'=>$cfg]);return ['saved'=>true];});
 }
 public function member($company,array $p){$this->permit($company,'manage');$user=coText($p['username']??'',100,true);$role=$p['role']??'';if(!in_array($role,['admin','accountant','assistant','auditor','manager'],true)||!$this->one('SELECT Usuario FROM Seg_Usuario WHERE Usuario=? AND COALESCE(Anulado,0)=0',[$user]))throw new InvalidArgumentException('Usuario o rol no válido.');return $this->transaction(function()use($company,$user,$role){$this->exec('INSERT INTO Co_Member(CompanyId,Username,Role) VALUES(?,?,?) ON DUPLICATE KEY UPDATE Role=VALUES(Role)',[$company,$user,$role]);$this->audit($company,'grant','member',$user,['role'=>$role]);return ['saved'=>true];});}
 public function branch($company,array $p){$this->permit($company,'manage');$warehouse=empty($p['warehouseId'])?null:(int)$p['warehouseId'];if($warehouse&&!$this->one('SELECT IdAlmacen FROM Lo_Almacen WHERE IdAlmacen=?',[$warehouse]))throw new InvalidArgumentException('Almacén de origen no disponible.');return $this->transaction(function()use($company,$p,$warehouse){$this->exec('INSERT INTO Co_Branch(CompanyId,Name,WarehouseId) VALUES(?,?,?)',[$company,coText($p['name']??'',160,true),$warehouse]);$id=$this->db->lastInsertId();$this->audit($company,'create','branch',$id,['warehouse'=>$warehouse]);return ['id'=>$id];});}
 public function accountRows($company){$this->permit($company);return $this->rows('SELECT * FROM Co_Account WHERE CompanyId=? ORDER BY Code',[$company]);}
 public function account($company,array $p){$this->permit($company,'manage');return $this->transaction(function()use($company,$p){$this->saveAccount($company,$p);$this->audit($company,'save','account',$p['code']);return ['saved'=>true];});}
 public function saveAccount($company,array $p){
  $code=(string)($p['code']??'');$parent=empty($p['parent'])?null:(string)$p['parent'];
  if(!preg_match('/^\d{2,20}$/',$code)||($parent&&(!preg_match('/^\d{2,19}$/',$parent)||strlen($parent)>=strlen($code)||strpos($code,$parent)!==0)))throw new InvalidArgumentException('Código/jerarquía de cuenta inválidos.');
  if(!in_array($p['nature']??'',['debit','credit'],true)||!in_array($p['class']??'',['asset','liability','equity','income','expense','memo'],true))throw new InvalidArgumentException('Naturaleza o clasificación inválida.');
  $group=coText($p['group']??'',60,true);$postable=empty($p['postable'])?0:1;$active=isset($p['active'])?(int)(bool)$p['active']:1;
  $used=$this->one("SELECT l.Id FROM Co_Line l JOIN Co_Entry e ON e.Id=l.EntryId AND e.CompanyId=l.CompanyId WHERE l.CompanyId=? AND l.Account=? AND e.Status='posted' LIMIT 1",[$company,$code]);
  $old=$this->one('SELECT * FROM Co_Account WHERE CompanyId=? AND Code=? FOR UPDATE',[$company,$code]);
  if($used&&($old['Nature']!==$p['nature']||$old['Class']!==$p['class']||$old['ReportGroup']!==$group||$old['ParentCode']!==$parent))throw new InvalidArgumentException('No reclasifiques una cuenta con asientos contabilizados. Crea una cuenta nueva.');
  if($postable&&$this->one('SELECT Code FROM Co_Account WHERE CompanyId=? AND ParentCode=? LIMIT 1',[$company,$code]))throw new InvalidArgumentException('Una cuenta con subcuentas no recibe movimientos.');
  if($parent){$pa=$this->one('SELECT * FROM Co_Account WHERE CompanyId=? AND Code=?',[$company,$parent]);if(!$pa||$pa['Postable'])throw new InvalidArgumentException('La cuenta padre debe existir y ser agrupadora.');}
  $this->exec('INSERT INTO Co_Account(CompanyId,Code,Name,ParentCode,Nature,Class,ReportGroup,Postable,Active) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE Name=VALUES(Name),ParentCode=VALUES(ParentCode),Nature=VALUES(Nature),Class=VALUES(Class),ReportGroup=VALUES(ReportGroup),Postable=VALUES(Postable),Active=VALUES(Active)',[$company,$code,coText($p['name']??'',200,true),$parent,$p['nature'],$p['class'],$group,$postable,$active]);
 }
 public function importAccounts($company,array $items){$this->permit($company,'manage');$seen=[];foreach($items as $item){if(!is_array($item))throw new InvalidArgumentException('Fila de cuenta inválida.');$code=coText((string)($item['code']??''),20,true);if(isset($seen[$code]))throw new InvalidArgumentException('Código de cuenta repetido en el archivo.');$seen[$code]=true;}if(!count($items)||count($items)>5000)throw new InvalidArgumentException('Importa entre 1 y 5000 cuentas.');usort($items,function($a,$b){return strlen($a['code'])<=>strlen($b['code'])?:strcmp($a['code'],$b['code']);});return $this->transaction(function()use($company,$items){foreach($items as $p)$this->saveAccount($company,$p);$this->audit($company,'import','accounts','catalog',['count'=>count($items)]);return ['count'=>count($items)];});}
 public function period($company,$period){$this->permit($company,'period');$period=coPeriod($period);return $this->transaction(function()use($company,$period){$this->exec('INSERT IGNORE INTO Co_Period(CompanyId,Period) VALUES(?,?)',[$company,$period]);$this->audit($company,'open','period',$period);return ['saved'=>true];});}
 public function lockPeriod($company,$period){$p=$this->one('SELECT * FROM Co_Period WHERE CompanyId=? AND Period=? FOR UPDATE',[$company,$period]);if(!$p||$p['State']!=='open')throw new InvalidArgumentException('El período no existe o está cerrado.');return $p;}
 public function closePeriod($company,array $p){$this->permit($company,!empty($p['reopen'])?'manage':'period');$period=coPeriod($p['period']??'');return $this->transaction(function()use($company,$period,$p){$state=$this->one('SELECT * FROM Co_Period WHERE CompanyId=? AND Period=? FOR UPDATE',[$company,$period]);if(!$state)throw new InvalidArgumentException('Período inexistente.');if(!empty($p['reopen'])){coText($p['reason']??'',500,true);$this->exec("UPDATE Co_Period SET State='open',ClosedBy=NULL,ClosedAt=NULL WHERE CompanyId=? AND Period=?",[$company,$period]);$this->audit($company,'reopen','period',$period,['reason'=>$p['reason']]);return ['saved'=>true];}
   if($this->one("SELECT Id FROM Co_Entry WHERE CompanyId=? AND Period=? AND Status IN ('draft','reviewed','approved') LIMIT 1",[$company,$period]))throw new InvalidArgumentException('Hay asientos pendientes en este período.');
   if($this->one("SELECT SourceId FROM Co_Source WHERE CompanyId=? AND State IN ('pending','conflict') AND JSON_UNQUOTE(JSON_EXTRACT(Snapshot,'$.date')) LIKE ? LIMIT 1",[$company,$period.'%']))throw new InvalidArgumentException('Hay operaciones de origen pendientes/conflictivas.');
   if($this->one("SELECT s.SourceId FROM Co_Source s JOIN Co_Entry e ON e.CompanyId=s.CompanyId AND e.Id=s.EntryId WHERE s.CompanyId=? AND s.State='generated' AND e.Status='discarded' AND JSON_UNQUOTE(JSON_EXTRACT(s.Snapshot,'$.date')) LIKE ? LIMIT 1",[$company,$period.'%']))throw new InvalidArgumentException('Hay documentos de origen cuyo borrador fue descartado. Resuelve su situación antes del cierre.');
   $this->exec("UPDATE Co_Period SET State='closed',ClosedBy=?,ClosedAt=? WHERE CompanyId=? AND Period=?",[$this->user,coNow(),$company,$period]);$this->audit($company,'close','period',$period);return ['saved'=>true];});}
 public function validateLines($company,array $lines,$rate){
  if(count($lines)<2||count($lines)>500)throw new InvalidArgumentException('El asiento requiere entre 2 y 500 líneas.');$debit=0;$credit=0;$originalDebit=0;$originalCredit=0;$result=[];
  foreach($lines as $l){$account=coText((string)($l['account']??''),20,true);if(!$this->one('SELECT Code FROM Co_Account WHERE CompanyId=? AND Code=? AND Active=1 AND Postable=1',[$company,$account]))throw new InvalidArgumentException('Cuenta inactiva, agrupadora o de otra empresa: '.$account);
   $od=coMoney($l['debit']??'0');$oc=coMoney($l['credit']??'0');if(($od>0)===($oc>0))throw new InvalidArgumentException('Cada línea debe tener un solo importe positivo en debe o haber.');$originalDebit+=$od;$originalCredit+=$oc;
   $d=coConvert($od,$rate);$c=coConvert($oc,$rate);if($d+$c===0)throw new InvalidArgumentException('Línea convertida a cero.');
   $flow=$l['cashFlow']??'';if(!in_array($flow,['','operating','investing','financing','fx'],true))throw new InvalidArgumentException('Clasificación de flujo inválida.');
   $debit+=$d;$credit+=$c;$result[]=['account'=>$account,'debit'=>$d,'credit'=>$c,'originalDebit'=>$od,'originalCredit'=>$oc,'partyType'=>coText($l['partyType']??'',15),'partyId'=>coText((string)($l['partyId']??''),40),'cashFlow'=>$flow,'memo'=>coText($l['memo']??'',500)];
  }if($debit!==$credit||$originalDebit!==$originalCredit)throw new InvalidArgumentException('Asiento descuadrado: debe '.coAmount($debit).' / haber '.coAmount($credit).'. Registra explícitamente diferencias de cambio o redondeo.');if(!$debit)throw new InvalidArgumentException('Asiento sin importe.');return $result;
 }
 public function draft($company,array $p){$c=$this->permit($company,'draft');return $this->transaction(function()use($company,$p,$c){return $this->insertDraft($company,$p,$c);});}
 public function insertDraft($company,array $p,array $c){
  $date=coDate($p['date']??'');$period=substr($date,0,7);$this->lockPeriod($company,$period);$currency=$p['currency']??$c['Currency'];if(!in_array($currency,['PEN','USD','EUR'],true))throw new InvalidArgumentException('Moneda no disponible.');$rate=coRate($p['rate']??'1');if($currency===$c['Currency']&&$rate!==1000000)throw new InvalidArgumentException('La moneda funcional usa tipo de cambio 1.');
  $branch=empty($p['branchId'])?null:(int)$p['branchId'];if($branch&&!$this->one('SELECT Id FROM Co_Branch WHERE CompanyId=? AND Id=?',[$company,$branch]))throw new InvalidArgumentException('Sucursal de otra empresa.');
  $lines=$this->validateLines($company,$p['lines']??[],$rate);$sourceType=coText($p['sourceType']??'manual',30,true);$sourceId=coText((string)($p['sourceId']??bin2hex(random_bytes(16))),100,true);if($sourceType==='opening'){if($this->one("SELECT Id FROM Co_Entry WHERE CompanyId=? AND Status='posted' AND EntryDate<? LIMIT 1",[$company,$date]))throw new InvalidArgumentException('Ya existen saldos anteriores; no se duplican con otra apertura.');foreach($lines as $l){$a=$this->one('SELECT Class FROM Co_Account WHERE CompanyId=? AND Code=?',[$company,$l['account']]);if(in_array($a['Class'],['income','expense'],true))throw new InvalidArgumentException('La apertura inicial registra saldos patrimoniales, no ingresos/gastos nuevos.');}}$hash=hash('sha256',coJson($p));$existing=$this->one('SELECT Id,SourceHash FROM Co_Entry WHERE CompanyId=? AND SourceType=? AND SourceId=? FOR UPDATE',[$company,$sourceType,$sourceId]);
  if($existing){if($existing['SourceHash']!==$hash)throw new InvalidArgumentException('La operación ya existe con datos distintos. Revisa y revierte; no se sobrescribe.');return ['id'=>(int)$existing['Id'],'duplicate'=>true];}
  $this->exec('INSERT INTO Co_Entry(CompanyId,BranchId,Period,EntryDate,Currency,ExchangeRate,Memo,SourceType,SourceId,SourceHash,Document,CreatedBy,CreatedAt) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$company,$branch,$period,$date,$currency,(string)($p['rate']??'1'),coText($p['memo']??'',500,true),$sourceType,$sourceId,$hash,coText($p['document']??'',100),$this->user,coNow()]);$id=(int)$this->db->lastInsertId();
  foreach($lines as $l)$this->exec('INSERT INTO Co_Line(CompanyId,EntryId,Account,Debit,Credit,OriginalDebit,OriginalCredit,PartyType,PartyId,CashFlow,Memo) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$company,$id,$l['account'],$l['debit'],$l['credit'],$l['originalDebit'],$l['originalCredit'],$l['partyType'],$l['partyId'],$l['cashFlow'],$l['memo']]);
  if(!empty($p['electronic']))$this->exec('UPDATE Co_Entry SET ElectronicData=? WHERE CompanyId=? AND Id=?',[coJson(coElectronic($p['electronic'])),$company,$id]);if(!empty($p['tax']))$this->insertTax($company,$id,$p['tax']);$this->audit($company,'create','entry',$id,['source'=>$sourceType,'hash'=>$hash]);return ['id'=>$id,'duplicate'=>false];
 }
 public function insertTax($company,$id,array $input){$d=coTax($input);$this->lockPeriod($company,$d['period']);$companyData=$this->one('SELECT Config FROM Co_Company WHERE Id=?',[$company]);$settings=json_decode($companyData['Config'],true);$sale=$d['kind']==='sale';$taxAccount=$settings['accounts'][$sale?'igv_output':'igv_input']??'';$expected=$sale?($d['igv']+$d['freeIgv']):($d['creditEligible']?$d['igv']:0);$balance=$this->one('SELECT COALESCE(SUM(OriginalDebit-OriginalCredit),0) Amount FROM Co_Line WHERE CompanyId=? AND EntryId=? AND Account=?',[$company,$id,$taxAccount]);$actual=(int)$balance['Amount']*($sale?-1:1);if($actual!==$expected*$d['sign'])throw new InvalidArgumentException('El IGV del registro no coincide con el asiento contable.');$fields=['kind','issueDate','period','docType','series','number','partyDocType','partyDoc','partyName','taxable','exempt','unaffected','freeAmount','freeIgv','igv','otherTaxes','total','withholding','perception','detraction','creditEligible','referenceDoc','sign'];$entry=$this->one('SELECT ExchangeRate FROM Co_Entry WHERE CompanyId=? AND Id=?',[$company,$id]);$rate=coRate($entry['ExchangeRate']);$args=[$company,$id];foreach($fields as $k)$args[]=in_array($k,['taxable','exempt','unaffected','freeAmount','freeIgv','igv','otherTaxes','total','withholding','perception','detraction'],true)?coConvert($d[$k],$rate):$d[$k];$args[]=coJson($input);$this->exec('INSERT INTO Co_TaxDocument(CompanyId,EntryId,Kind,IssueDate,TaxPeriod,DocType,Series,DocNumber,PartyDocType,PartyDoc,PartyName,Taxable,Exempt,Unaffected,FreeAmount,FreeIgv,Igv,OtherTaxes,Total,Withholding,Perception,Detraction,CreditEligible,ReferenceDoc,Sign,OriginalData) VALUES('.implode(',',array_fill(0,count($args),'?')).')',$args);}
 public function updateDraft($company,array $p){$this->permit($company,'draft');return $this->transaction(function()use($company,$p){$e=$this->one('SELECT * FROM Co_Entry WHERE CompanyId=? AND Id=? FOR UPDATE',[$company,(int)($p['id']??0)]);if(!$e||$e['Status']!=='draft'||$e['SourceType']!=='manual'||(int)$e['Version']!==(int)($p['version']??0))throw new InvalidArgumentException('Solo se editan borradores manuales vigentes.');$this->lockPeriod($company,$e['Period']);$lines=$this->validateLines($company,$p['lines']??[],coRate($e['ExchangeRate']));$before=$this->rows('SELECT * FROM Co_Line WHERE CompanyId=? AND EntryId=?',[$company,$e['Id']]);$this->exec('DELETE FROM Co_Line WHERE CompanyId=? AND EntryId=?',[$company,$e['Id']]);foreach($lines as $l)$this->exec('INSERT INTO Co_Line(CompanyId,EntryId,Account,Debit,Credit,OriginalDebit,OriginalCredit,PartyType,PartyId,CashFlow,Memo) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$company,$e['Id'],$l['account'],$l['debit'],$l['credit'],$l['originalDebit'],$l['originalCredit'],$l['partyType'],$l['partyId'],$l['cashFlow'],$l['memo']]);$memo=coText($p['memo']??'',500,true);$electronic=empty($p['electronic'])?$e['ElectronicData']:coJson(coElectronic($p['electronic']));$this->exec('UPDATE Co_Entry SET Memo=?,ElectronicData=?,Version=Version+1 WHERE CompanyId=? AND Id=?',[$memo,$electronic,$company,$e['Id']]);$this->audit($company,'edit_draft','entry',$e['Id'],['before'=>$before,'after'=>$lines,'memo'=>$memo]);return ['id'=>(int)$e['Id']];});}
 public function yearClosing($company,array $p){$c=$this->permit($company,'period');$year=(int)($p['year']??0);if($year<2000||$year>2100)throw new InvalidArgumentException('Ejercicio inválido.');$account=$c['settings']['accounts']['retained']??'';if(!$account)throw new InvalidArgumentException('Configura resultados acumulados.');$end=$year.'-12-31';return $this->transaction(function()use($company,$c,$year,$account,$end){$this->lockPeriod($company,$year.'-12');$balances=$this->rows("SELECT l.Account,SUM(l.Debit-l.Credit) Balance FROM Co_Line l JOIN Co_Entry e ON e.CompanyId=l.CompanyId AND e.Id=l.EntryId JOIN Co_Account a ON a.CompanyId=l.CompanyId AND a.Code=l.Account WHERE l.CompanyId=? AND e.Status='posted' AND e.EntryDate<=? AND a.Class IN ('income','expense') GROUP BY l.Account HAVING SUM(l.Debit-l.Credit)<>0",[$company,$end]);$lines=[];$difference=0;foreach($balances as $b){$v=(int)$b['Balance'];$difference+=$v;$lines[]=['account'=>$b['Account'],'debit'=>$v<0?coAmount(-$v):'0','credit'=>$v>0?coAmount($v):'0'];}if(!$lines)throw new InvalidArgumentException('No hay resultados pendientes de cierre.');if($difference)$lines[]=['account'=>$account,'debit'=>$difference>0?coAmount($difference):'0','credit'=>$difference<0?coAmount(-$difference):'0'];$p=['date'=>$end,'currency'=>'PEN','rate'=>'1','memo'=>'Cierre de resultados del ejercicio '.$year,'sourceType'=>'closing','sourceId'=>(string)$year,'lines'=>$lines];return $this->insertDraft($company,$p,$c);});}
 public function voidTax($company,array $p){$this->permit($company,'approve');return $this->transaction(function()use($company,$p){$tax=$this->one('SELECT * FROM Co_TaxDocument WHERE CompanyId=? AND EntryId=? FOR UPDATE',[$company,(int)($p['id']??0)]);if(!$tax||$tax['State']!=='active')throw new InvalidArgumentException('Documento tributario no disponible.');$this->lockPeriod($company,$tax['TaxPeriod']);if(!$this->one("SELECT Id FROM Co_Entry WHERE CompanyId=? AND ReversalOf=? AND Status='posted'",[$company,$tax['EntryId']]))throw new InvalidArgumentException('Contabiliza primero el reverso del asiento. Una nota de crédito se registra como documento nuevo, no como anulación.');$reason=coText($p['evidence']??'',500,true);$this->exec("UPDATE Co_TaxDocument SET State='void',VoidReason=?,VoidBy=?,VoidAt=? WHERE CompanyId=? AND Id=?",[$reason,$this->user,coNow(),$company,$tax['Id']]);$this->audit($company,'void_document','tax',$tax['Id'],['evidence'=>$reason,'original'=>$tax['OriginalData']]);return ['saved'=>true];});}
 public function entries($company,array $p){$this->permit($company);$args=[$company];$where='e.CompanyId=?';foreach(['from'=>'EntryDate>=','to'=>'EntryDate<='] as $k=>$expr)if(!empty($p[$k])){$where.=' AND e.'.$expr.'?';$args[]=coDate($p[$k]);}if(!empty($p['status'])){$where.=' AND e.Status=?';$args[]=$p['status'];}if(!empty($p['branchId'])){$where.=' AND e.BranchId=?';$args[]=(int)$p['branchId'];}return $this->rows('SELECT e.*,SUM(l.Debit) Debit,SUM(l.Credit) Credit FROM Co_Entry e JOIN Co_Line l ON l.EntryId=e.Id AND l.CompanyId=e.CompanyId WHERE '.$where.' GROUP BY e.Id ORDER BY e.EntryDate DESC,e.Id DESC LIMIT 1000',$args);}
 public function entry($company,$id){$this->permit($company);$e=$this->one('SELECT * FROM Co_Entry WHERE CompanyId=? AND Id=?',[$company,$id]);if(!$e)throw new InvalidArgumentException('Asiento no disponible.');$e['lines']=$this->rows('SELECT l.*,a.Name AccountName FROM Co_Line l JOIN Co_Account a ON a.CompanyId=l.CompanyId AND a.Code=l.Account WHERE l.CompanyId=? AND l.EntryId=? ORDER BY l.Id',[$company,$id]);$e['tax']=$this->one('SELECT * FROM Co_TaxDocument WHERE CompanyId=? AND EntryId=?',[$company,$id]);return $e;}
 public function transition($company,array $p){$action=$p['action']??'';$map=['review'=>['draft','reviewed','ReviewedBy'],'approve'=>['reviewed','approved','ApprovedBy'],'post'=>['approved','posted','PostedBy'],'discard'=>['draft','discarded','CreatedBy']];if(!isset($map[$action]))throw new InvalidArgumentException('Transición inválida.');$c=$this->permit($company,$action==='discard'?'draft':$action);return $this->transaction(function()use($company,$p,$action,$map,$c){$e=$this->one('SELECT * FROM Co_Entry WHERE CompanyId=? AND Id=? FOR UPDATE',[$company,(int)$p['id']]);if(!$e||(int)$e['Version']!==(int)($p['version']??0)||$e['Status']!==$map[$action][0])throw new InvalidArgumentException('El asiento cambió o no admite esta transición.');$period=$this->lockPeriod($company,$e['Period']);
   if(in_array($action,['review','approve'],true)&&!empty($c['settings']['fourEyes'])&&$e['CreatedBy']===$this->user)throw new InvalidArgumentException('Requiere revisión/aprobación de otro usuario.');
   $sum=$this->one('SELECT SUM(Debit) D,SUM(Credit) C FROM Co_Line WHERE CompanyId=? AND EntryId=?',[$company,$e['Id']]);if((int)$sum['D']!==(int)$sum['C']||(int)$sum['D']<=0)throw new InvalidArgumentException('Asiento descuadrado.');
   if($action==='post'&&$this->one('SELECT l.Id FROM Co_Line l JOIN Co_Account a ON a.CompanyId=l.CompanyId AND a.Code=l.Account WHERE l.CompanyId=? AND l.EntryId=? AND (a.Active=0 OR a.Postable=0 OR l.Debit<0 OR l.Credit<0 OR (l.Debit>0 AND l.Credit>0)) LIMIT 1',[$company,$e['Id']]))throw new InvalidArgumentException('El asiento contiene cuentas deshabilitadas o líneas inválidas.');
   if($action==='post'){$this->exec('UPDATE Co_Period SET NextNumber=NextNumber+1 WHERE CompanyId=? AND Period=?',[$company,$e['Period']]);$this->exec('UPDATE Co_Entry SET Number=?,PostedAt=? WHERE CompanyId=? AND Id=?',[$period['NextNumber'],coNow(),$company,$e['Id']]);}
   if($action==='discard')$this->exec('UPDATE Co_Entry SET Status=?,Version=Version+1 WHERE CompanyId=? AND Id=?',[$map[$action][1],$company,$e['Id']]);else $this->exec('UPDATE Co_Entry SET Status=?,'.$map[$action][2].'=?,Version=Version+1 WHERE CompanyId=? AND Id=?',[$map[$action][1],$this->user,$company,$e['Id']]);$this->audit($company,$action,'entry',$e['Id']);return ['id'=>(int)$e['Id'],'status'=>$map[$action][1]];});}
 public function reverse($company,array $p){$c=$this->permit($company,'reverse');return $this->transaction(function()use($company,$p,$c){$e=$this->one("SELECT * FROM Co_Entry WHERE CompanyId=? AND Id=? AND Status='posted' FOR UPDATE",[$company,(int)$p['id']]);if(!$e||(int)$e['Version']!==(int)($p['version']??0))throw new InvalidArgumentException('Asiento no disponible para reverso.');if($e['ReversalOf'])throw new InvalidArgumentException('No reviertas un reverso; registra un ajuste enlazado.');coText($p['reason']??'',500,true);
   $date=coDate($p['date']??'');if($date<$e['EntryDate'])throw new InvalidArgumentException('El reverso no puede preceder al asiento.');$lines=[];foreach($this->rows('SELECT * FROM Co_Line WHERE CompanyId=? AND EntryId=?',[$company,$e['Id']]) as $l)$lines[]=['account'=>$l['Account'],'debit'=>coAmount((int)$l['OriginalCredit']),'credit'=>coAmount((int)$l['OriginalDebit']),'partyType'=>$l['PartyType'],'partyId'=>$l['PartyId'],'cashFlow'=>$l['CashFlow'],'memo'=>$p['reason']];
   $result=$this->insertDraft($company,['date'=>$date,'currency'=>$e['Currency'],'rate'=>$e['ExchangeRate'],'branchId'=>$e['BranchId'],'memo'=>'Reverso #'.$e['Id'].': '.$p['reason'],'sourceType'=>'reversal','sourceId'=>(string)$e['Id'],'document'=>$e['Document'],'lines'=>$lines],$c);$this->exec('UPDATE Co_Entry SET ReversalOf=? WHERE CompanyId=? AND Id=?',[$e['Id'],$company,$result['id']]);$this->audit($company,'reverse_requested','entry',$e['Id'],['reversal'=>$result['id'],'reason'=>$p['reason']]);return $result;});}
